import requests
import zipfile
import xml.etree.ElementTree as ET
import io

def get_shared_strings(zf):
    with zf.open('xl/sharedStrings.xml') as f:
        tree = ET.parse(f)
        root = tree.getroot()
        ns = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
        strings = []
        for si in root.findall('s:si', ns):
            texts = []
            for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'):
                if t.text:
                    texts.append(t.text)
            strings.append(''.join(texts))
    return strings

def download_asset(aid):
    url = f"https://dam-api.bfs.admin.ch/hub/api/dam/assets/{aid}/master"
    r = requests.get(url, headers={"User-Agent": "Mozilla/5.0"})
    if r.status_code == 200:
        return r.content
    return None

for aid in [36073664, 36073662]:
    print(f"=== Asset {aid} ===")
    data = download_asset(aid)
    if data:
        zf = zipfile.ZipFile(io.BytesIO(data))
        strings = get_shared_strings(zf)
        # Search for migration keywords
        found = False
        for i, s in enumerate(strings):
            if 'migrat' in s.lower() or 'hintergrund' in s.lower() or 'migrationsstatus' in s.lower():
                print(f"  Found: [{i}] {s}")
                found = True
        if not found:
            print("  No migration keywords found.")
        # Print first 30 strings to see title
        print("  First 30 strings:")
        for i, s in enumerate(strings[:30]):
            print(f"    [{i}] {s}")
    else:
        print("  Download failed")
    print()
